/* Customer master and one-to-many contracts, using server-side scope and version checks. */
'use strict';
const ArchiveDate=value=>value?new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Lubumbashi',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value)).replaceAll('-','/'):'—';
const ContractNames={VALID:'有效期内',UPCOMING:'尚未生效',EXPIRED:'已到期',INACTIVE:'已停用'};
Object.assign(Business,{
 async customers(){const d=await this.load(),q=new URLSearchParams(location.search),r=await API.request('/contracts?'+q);this.open('客户管理',`<div class="business-toolbar"><button id="customer-new" class="button primary" ${this.can('customer:write')?'':'disabled'}>新增客户</button><button id="contract-new" class="button secondary" ${this.can('customer:write')?'':'disabled'}>新增合同</button></div><form id="contract-filter" class="business-toolbar"><label>搜索合同号 / 客户<input name="search" value="${esc(q.get('search')||'')}"></label><label>有效期状态<select name="validity"><option value="">全部</option>${Object.entries(ContractNames).map(([k,v])=>`<option value="${k}" ${q.get('validity')===k?'selected':''}>${v}</option>`).join('')}</select></label><button class="button secondary">筛选</button></form><h3>客户档案</h3><div class="business-table"><table><thead><tr><th>客户名称</th><th>客户代码</th><th>客户地址</th><th>客户邮箱</th><th>客户联系方式</th><th>档案创建日期</th><th>状态</th><th>操作</th></tr></thead><tbody>${d.customers.map(c=>`<tr><td data-no-i18n>${esc(c.name)}</td><td data-no-i18n>${esc(c.code)}</td><td data-no-i18n>${esc(c.address||'—')}</td><td data-no-i18n>${esc(c.email||'—')}</td><td data-no-i18n>${esc(c.phone||'—')}</td><td data-no-i18n>${ArchiveDate(c.created_at)}</td><td>${c.active?'启用':'停用'}</td><td><button data-customer-edit="${c.id}" class="button secondary compact" ${this.can('customer:write')?'':'disabled'}>编辑</button></td></tr>`).join('')}</tbody></table></div><h3>合同档案（一客户多合同）</h3><p>新计划与新备货必须使用有效合同；合同号可修正，关联客户与历史单据保持可追溯。到期、停用不删除既有业务历史。</p><div class="business-table"><table><thead><tr><th>合同号</th><th>客户名称</th><th>生效日期</th><th>截止日期</th><th>合同创建日期</th><th>启停状态</th><th>有效期状态</th><th>操作</th></tr></thead><tbody>${r.items.map(k=>`<tr><td>${esc(k.contract_no)}</td><td>${esc(k.customer_name)}</td><td>${esc(k.effective_date)}</td><td>${esc(k.end_date)}</td><td data-no-i18n>${ArchiveDate(k.created_at)}</td><td>${k.active?'启用':'停用'}</td><td>${esc(ContractNames[k.validity])}</td><td><a class="button secondary compact" href="/customers/contracts/${k.id}">查看</a> <button class="button secondary compact" data-contract-edit="${k.id}" ${this.can('customer:write')?'':'disabled'}>编辑</button> ${this.can('customer:write')?`<button class="button danger-outline compact" data-contract-delete="${k.id}">删除</button>`:''}</td></tr>`).join('')||'<tr><td colspan="8">暂无匹配合同；历史计划未自动关联合同。</td></tr>'}</tbody></table></div>`);$('customer-new').onclick=()=>this.masterForm('customers');$('contract-new').onclick=()=>this.contractForm();document.querySelectorAll('[data-customer-edit]').forEach(b=>b.onclick=()=>this.masterForm('customers',d.customers.find(c=>c.id===b.dataset.customerEdit)));document.querySelectorAll('[data-contract-edit]').forEach(b=>b.onclick=()=>this.contractForm(r.items.find(k=>k.id===b.dataset.contractEdit)));document.querySelectorAll('[data-contract-delete]').forEach(b=>b.onclick=()=>this.contractRemove(r.items.find(k=>k.id===b.dataset.contractDelete)));$('contract-filter').onsubmit=e=>{e.preventDefault();Router.go('/customers?'+new URLSearchParams(new FormData(e.target)));};},
 async contractForm(k={}){if(k.deleted_at)throw Error('已删除合同不可编辑');const d=await this.load();this.open(k.id?'编辑合同':'新增客户合同',`<form class="user-form" id="contract-form"><div class="form-grid"><label>项目<select name="project_id" ${k.id?'disabled':''}>${this.options(d.projects,k.project_id,'name')}</select></label><label>客户名称<select name="customer_id" ${k.id?'disabled':''}>${this.options(d.customers,k.customer_id,'name')}</select></label><label>合同号<input name="contract_no" required maxlength="80" value="${esc(k.contract_no||'')}"></label><label>合同生效日期<input name="effective_date" type="date" required value="${esc(k.effective_date||'')}"></label><label>合同截止日期<input name="end_date" type="date" required value="${esc(k.end_date||'')}"></label><label>启停状态<select name="active"><option value="true">启用</option><option value="false" ${k.active===false?'selected':''}>停用</option></select></label></div><p>有效期按刚果金业务日期（Africa/Lubumbashi）由服务器判定。停用或到期后不能新增备货，历史记录继续保留。</p><p class="error" id="contract-error" role="alert"></p><button class="button primary">保存合同</button></form>`);$('contract-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const body=Object.fromEntries(new FormData(e.target));body.active=body.active==='true';if(k.id)body.version=k.version;const r=await API.request('/contracts'+(k.id?'/'+k.id:''),{method:k.id?'PATCH':'POST',body});await this.contractDetail(r.id);notify('合同已保存');}catch(err){$('contract-error').textContent=err.message;e.submitter.disabled=false;}};},
 async contractDetail(id){const k=await API.request('/contracts/'+id);this.open('合同 · '+k.contract_no,`${k.deleted_at?'<p class="dialog-notice">合同已删除，历史关联保留。</p>':''}<dl>${[['客户名称',k.customer_name],['合同号',k.contract_no],['合同生效日期',k.effective_date],['合同截止日期',k.end_date],['启停状态',k.active?'启用':'停用'],['有效期状态',ContractNames[k.validity]],['版本',k.version]].map(([l,v])=>`<dt>${esc(l)}</dt><dd>${esc(v)}</dd>`).join('')}</dl>${!k.deleted_at&&this.can('customer:write')?'<button id="contract-edit" class="button primary">编辑</button><button id="contract-delete" class="button danger-outline">删除</button>':''}<a class="button secondary" href="/customers">返回客户管理</a>`);if($('contract-edit'))$('contract-edit').onclick=()=>this.contractForm(k);if($('contract-delete'))$('contract-delete').onclick=()=>this.contractRemove(k);},
 contractRemove(k){dialog('删除合同档案',`<p>删除后从合同档案列表移除，不再用于新销售计划。关联单据和历史记录保留。</p><p><strong data-no-i18n>${esc(k.contract_no)}</strong> · <span data-no-i18n>${esc(k.customer_name)}</span></p><form id="contract-delete-form" class="user-form"><label>删除说明（选填）<textarea name="reason" maxlength="1000"></textarea></label><p id="contract-delete-error" class="error" role="alert"></p><div class="business-toolbar"><button class="button danger" type="submit">确认删除</button><button class="button secondary" type="button" id="contract-delete-cancel">取消</button></div></form>`);$('contract-delete-cancel').onclick=()=>$('dialog').close();$('contract-delete-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await API.request('/contracts/'+k.id,{method:'DELETE',body:{version:k.version,reason:new FormData(e.target).get('reason')}});$('dialog').close();await Router.go('/customers');notify('合同已删除，业务历史已保留');}catch(err){$('contract-delete-error').textContent=err.message;e.submitter.disabled=false;}};}

});
